mapper.select:
SELECT A.WIDGET_ID AS widgetId , A.WIDGET_NAME AS widgetName , B.DATASET_TY AS datasetTy , C.STYLE_TY AS styleTy , A.USE_FL AS useFl , DATE_FORMAT(IFNULL(A.UPDATE_DT, A.CREATION_DT), '%Y-%m-%d') AS modifyDt FROM CM_WIDGET A INNER JOIN CM_WIDGET_DATASET B ON A.DATASET_ID = B.DATASET_ID AND A.CMPNY_CD = B.CMPNY_CD INNER JOIN CM_WIDGET_STYLE C ON A.STYLE_ID = C.STYLE_ID AND A.CMPNY_CD = C.CMPNY_CD WHERE A.CMPNY_CD = #{cmpnyCd}
AND A.CATEGORY_CD = #{categoryCd}
AND A.WIDGET_NAME LIKE CONCAT('%', #{widgetName}, '%')
ORDER BY A.WIDGET_ID ASC

mapper.insert:
INSERT INTO CM_WIDGET (
    WIDGET_ID
  , CMPNY_CD
  , WIDGET_NAME
  , DATASET_ID
  , STYLE_ID
  , CATEGORY_CD
  , MAPPING_JSON
  , CONFIG_JSON
  , FILE_SQ
  , USE_FL
  , CREATION_ID
  , UPDATE_ID
) VALUES (
    #{widgetId}
  , #{cmpnyCd}
  , #{widgetName}
  , #{datasetId}
  , #{styleId}
  , #{categoryCd}
  , 
        CAST(#{mappingJson} AS JSON)
        NULL

  , 
        CAST(#{configJson} AS JSON)
        NULL

  , 
        CAST(#{fileSq} AS DECIMAL(30,0))
        NULL

  , #{useFl}
  , #{creationId}
  , #{updateId}
)

mapper.update:
UPDATE CM_WIDGET
   SET WIDGET_NAME = #{widgetName}
     , DATASET_ID = #{datasetId}
     , STYLE_ID = #{styleId}
     , CATEGORY_CD = #{categoryCd}
     , MAPPING_JSON = CAST(#{mappingJson} AS JSON)
     , CONFIG_JSON = CAST(#{configJson} AS JSON)
     , FILE_SQ = 
        CAST(#{fileSq} AS DECIMAL(30,0))
        NULL

     , USE_FL = #{useFl}
     , UPDATE_ID = #{updateId}
     , UPDATE_DT = NOW()
 WHERE WIDGET_ID = #{widgetId}
   AND CMPNY_CD = #{cmpnyCd}

mapper.delete:
DELETE FROM CM_WIDGET_AUTHOR
 WHERE WIDGET_ID = #{widgetId}
   AND CMPNY_CD = #{cmpnyCd}

