INSERT INTO CM_FILE (
    FILE_SQ
  , FILE_TY
  , FILE_NM
  , SAVE_TY
  , MIME_TY
  , FILE_EXT
  , FILE_PATH
  , FILE_DATA
  , FILE_SIZE
  , USE_FL
  , CREATION_ID
  , UPDATE_ID
) VALUES (
    CAST(#{fileSq} AS DECIMAL(30,0))
  , 'WIDGET'
  , #{fileNm}
  , 'DATA'
  , #{mimeTy}
  , #{fileExt}
  , NULL
  , #{fileData, jdbcType=BLOB}
  , #{fileSize}
  , 'Y'
  , #{creationId}
  , #{updateId}
)

